ee:message.ee:set-payload:
%dw 2.0
output application/json
var communityPlusLogin = (vars.profileIds filter($.Name == p('sfProfileName.communityPlusLogin'))).Id[0]
---
vars.validWorkers map ((item,index)->
	do {	
	var userData = (vars.userSFEmployeeNumbers filter($.EmployeeNumber == item.EmpId))[0]
	---
	{
	"Manager__c": do{
		var userManagerData = (vars.userSFEmployeeNumbers filter($.EmployeeNumber == item.JobPositionDetail.SupervisorEmpId))[0]
		---
		if (userManagerData != null and userManagerData.IsActive == "true") userManagerData.Id
        else "#N/A"
	},
	"User__c":		
		if (userData != null) userData.Id
          else "#N/A",
	"OwnerId": 
    	if (userData != null and userData.IsActive == "true" and communityPlusLogin != null and userData.ProfileId != communityPlusLogin)
            userData.Id
        else null,        
    "Id": (vars.contactDetails filter($.Employee_ID__c == item.EmpId))[0].Id default "",	
    "Employee_ID__c": item.EmpId
	}
})
